with open('src/CompilerLib/backends/interp/InterpBackend.fdsl', 'r', encoding='utf-8') as f:
    text = f.read()

# Replace single-line compound statements
text = text.replace('{ found = true; break }', '{\n                                                                                                found = true\n                                                                                                break\n                                                                                          }')
text = text.replace('{ cpos = pi; break }', '{\n                                                                                                cpos = pi\n                                                                                                break\n                                                                                          }')
text = text.replace('{ colpos = a2i; break }', '{\n                                                                  colpos = a2i\n                                                                  break\n                                                            }')
text = text.replace('{ has_minus = true; break }', '{\n                                                                  has_minus = true\n                                                                  break\n                                                            }')
text = text.replace('{ inv = inv + "-"; ci = ci + 1 }', '{\n                                                                  inv = inv + "-"\n                                                                  ci = ci + 1\n                                                            }')
text = text.replace('{ inv = inv + "+"; ci = ci + 1 }', '{\n                                                                  inv = inv + "+"\n                                                                  ci = ci + 1\n                                                            }')
text = text.replace('{ inv = inv + cs[ci]; ci = ci + 1 }', '{\n                                                                  inv = inv + cs[ci]\n                                                                  ci = ci + 1\n                                                            }')
text = text.replace('route { stdMapContainsKey(reg_types, a1) ==> { t1 = reg_types[a1] }; _ ==> {} }', 'route {\n                                                            stdMapContainsKey(reg_types, a1) ==> { t1 = reg_types[a1] }\n                                                            _ ==> {}\n                                                      }')
text = text.replace('route { stdMapContainsKey(reg_types, a2) ==> { t2 = reg_types[a2] }; _ ==> {} }', 'route {\n                                                            stdMapContainsKey(reg_types, a2) ==> { t2 = reg_types[a2] }\n                                                            _ ==> {}\n                                                      }')
text = text.replace('route { stdMapContainsKey(reg_types, a2) ==> { a2_t = reg_types[a2] }; _ ==> {} }', 'route {\n                                                      stdMapContainsKey(reg_types, a2) ==> { a2_t = reg_types[a2] }\n                                                      _ ==> {}\n                                                }')
text = text.replace('route { stdMapContainsKey(reg_types, a1) ==> { ptype = reg_types[a1] }; _ ==> {} }', 'route {\n                                                      stdMapContainsKey(reg_types, a1) ==> { ptype = reg_types[a1] }\n                                                      _ ==> {}\n                                                }')

with open('src/CompilerLib/backends/interp/InterpBackend.fdsl', 'w', encoding='utf-8') as f:
    f.write(text)
print('InterpBackend.fdsl updated!')
